static void hl_release_Ctx(void* pv) {
    Ctx* p = (Ctx*)pv;
    if (!p) return;
    if (--p->refcnt == 0) {
        hl_str_release(p->f_src);
        hl_list_release(p->f_toks);
        hl_list_release(p->f_exprs);
        hl_list_release(p->f_stmts);
        hl_list_release(p->f_match_arms);
        hl_map_release(p->f_structs);
        hl_map_release(p->f_enums);
        hl_map_release(p->f_fns);
        hl_list_release(p->f_fn_order);
        hl_map_release(p->f_methods_of);
        hl_list_release(p->f_out);
        hl_map_release(p->f_gen_locals);
        hl_map_release(p->f_gen_counts);
        hl_map_release(p->f_gen_cnames);
        hl_map_release(p->f_edges);
        hl_list_release(p->f_imports);
        hl_list_release(p->f_loaded_files);
        hl_str_release(p->f_entry_dir);
        hl_str_release(p->f_repo_root);
        hl_str_release(p->f_cur_fn_ret);
        hl_str_release(p->f_cur_fn);
        hl_list_release(p->f_cur_typeparams);
        hl_list_release(p->f_cur_targs);
        hl_list_release(p->f_fn_insts);
        hl_list_release(p->f_struct_insts);
        hl_list_release(p->f_enum_insts);
        hl_map_release(p->f_computed_effects);
        hl_map_release(p->f_hoist_map);
        hl_list_release(p->f_hoist_flight);
        hl_list_release(p->f_null_after);
        hl_list_release(p->f_clone_insts);
        hl_list_release(p->f_loop_brk_frames);
        hl_list_release(p->f_loop_cont_frames);
        hl_list_release(p->f_spawn_decls);
        hl_map_release(p->f_pgo_counts);
        hl_list_release(p->f_pgo_site_ids);
        hl_map_release(p->f_pgo_site_map);
        hl_map_release(p->f_pgo_fn_sizes);
        hl_list_release(p->f_pgo_slits);
        hl_map_release(p->f_lto_calls);
        hl_map_release(p->f_lto_fn_start);
        hl_list_release(p->f_lto_inlined_report);
        hl_str_release(p->f_lto_splice_temp);
        hl_str_release(p->f_lto_splice_label);
        hl_str_release(p->f_target_feature);
        hl_list_release(p->f_simd_helpers_main);
        hl_list_release(p->f_simd_helpers_alt);
        hl_list_release(p->f_simd_helpers_plain);
        hl_list_release(p->f_simd_helpers_neon);
        hl_list_release(p->f_simd_helpers_rvv);
        hl_list_release(p->f_simd_helper_names);
        hl_str_release(p->f_cur_attrs_inline);
        hl_map_release(p->f_layout_map);
        hl_map_release(p->f_layout_why);
        hl_map_release(p->f_layout_cap);
        hl_list_release(p->f_layout_order);
        hl_str_release(p->f_cur_attrs_section);
        hl_str_release(p->f_cur_attrs_secrets);
        hl_str_release(p->f_cur_attrs_deprecated_msg);
        hl_str_release(p->f_cur_attrs_taint_sinks);
        hl_str_release(p->f_tail_label);
        hl_list_release(p->f_tail_params);
        hl_map_release(p->f_tail_sites);
        hl_str_release(p->f_stack_budget_path);
        hl_str_release(p->f_crate_link_script);
        hl_list_release(p->f_link_script_patterns);
        hl_str_release(p->f_crate_boot_header);
        hl_map_release(p->f_alloc_sites);
        hl_list_release(p->f_irq_proof_lines);
        hl_str_release(p->f_target_triple);
        hl_str_release(p->f_out_name);
        hl_str_release(p->f_symbols_path);
        hl_str_release(p->f_cur_map_file);
        hl_list_release(p->f_symtab);
        hl_map_release(p->f_rpreds);
        hl_map_release(p->f_rp_checked);
        hl_str_release(p->f_rp_pending);
        hl_map_release(p->f_cap_taken);
        free(p);
    }
}
static void hl_cleanup_Ctx(Ctx** p) { hl_release_Ctx(*p); }

typedef struct EscRec {
    int64_t refcnt;
    hl_str* f_name;
    int64_t f_line;
    int64_t f_cap;
    bool f_forced;
    bool f_boxed;
    hl_str* f_esc;
    int64_t f_esc_line;
    bool f_push;
    int64_t f_push_line;
    bool f_pop;
    int64_t f_pop_line;
} EscRec;

static EscRec* usf_new_EscRec(hl_str* f_name, int64_t f_line, int64_t f_cap, bool f_forced, bool f_boxed, hl_str* f_esc, int64_t f_esc_line, bool f_push, int64_t f_push_line, bool f_pop, int64_t f_pop_line) {
    EscRec* p = (EscRec*)malloc(sizeof(EscRec));
    if (!p) hl_die("out of memory");
    p->refcnt = 1;
    p->f_name = f_name;
    p->f_line = f_line;
    p->f_cap = f_cap;
    p->f_forced = f_forced;
    p->f_boxed = f_boxed;
    p->f_esc = f_esc;
    p->f_esc_line = f_esc_line;
    p->f_push = f_push;
    p->f_push_line = f_push_line;
    p->f_pop = f_pop;
    p->f_pop_line = f_pop_line;
    return p;
}

static void hl_release_EscRec(void* pv) {
    EscRec* p = (EscRec*)pv;
    if (!p) return;
    if (--p->refcnt == 0) {
        hl_str_release(p->f_name);
        hl_str_release(p->f_esc);
        free(p);
    }
}
static void hl_cleanup_EscRec(EscRec** p) { hl_release_EscRec(*p); }

typedef struct IVal {
    int64_t refcnt;
    int64_t f_lo;
    int64_t f_hi;
} IVal;

static IVal* usf_new_IVal(int64_t f_lo, int64_t f_hi) {
    IVal* p = (IVal*)malloc(sizeof(IVal));
    if (!p) hl_die("out of memory");
    p->refcnt = 1;
    p->f_lo = f_lo;
    p->f_hi = f_hi;
    return p;
}

static void hl_release_IVal(void* pv) {
    IVal* p = (IVal*)pv;
    if (!p) return;
    if (--p->refcnt == 0) {
        free(p);
    }
}
static void hl_cleanup_IVal(IVal** p) { hl_release_IVal(*p); }

