    hl_list_push(u_r, hl_cstr("#elif defined(__aarch64__)"));
    hl_list_push(u_r, hl_cstr("#define HL_SYS_read 63L"));
    hl_list_push(u_r, hl_cstr("#define HL_SYS_write 64L"));
