    hl_list_push(u_r, hl_cstr("#define HL_SYS_exit_group 94L"));
    hl_list_push(u_r, hl_cstr("#define HL_SYS_openat 56L"));
    hl_list_push(u_r, hl_cstr("#define HL_SYS_newfstatat 79L"));
