    hl_list_push(u_r, hl_cstr("#define HL_SYS_write 64L"));
    hl_list_push(u_r, hl_cstr("#define HL_SYS_close 57L"));
    hl_list_push(u_r, hl_cstr("#define HL_SYS_mmap 222L"));
    hl_list_push(u_r, hl_cstr("#define HL_SYS_getcwd 17L"));
    hl_list_push(u_r, hl_cstr("#define HL_SYS_exit_group 94L"));
    hl_list_push(u_r, hl_cstr("#define HL_SYS_openat 56L"));
    hl_list_push(u_r, hl_cstr("#define HL_SYS_newfstatat 79L"));
    hl_list_push(u_r, hl_cstr("#endif"));
    hl_list_push(u_r, hl_cstr("#define HL_AT_FDCWD (-100L)"));
    hl_list_push(u_r, hl_cstr("#define HL_O_RDONLY 0L"));
    hl_list_push(u_r, hl_cstr("#define HL_O_WRONLY 1L"));
    hl_list_push(u_r, hl_cstr("#define HL_O_CREAT 64L"));
    hl_list_push(u_r, hl_cstr("#define HL_O_TRUNC 512L"));
    hl_list_push(u_r, hl_cstr("static long hl_nl_sys(long n, long a1, long a2, long a3, long a4, long a5, long a6) {"));
    hl_list_push(u_r, hl_cstr("    long ret;"));
    hl_list_push(u_r, hl_cstr("#if defined(__x86_64__)"));
    hl_list_push(u_r, hl_cstr("    register long r10 __asm__(\"r10\") = a4;"));
    hl_list_push(u_r, hl_cstr("    register long r8 __asm__(\"r8\") = a5;"));
    hl_list_push(u_r, hl_cstr("    register long r9 __asm__(\"r9\") = a6;"));
    hl_list_push(u_r, hl_cstr("    __asm__ volatile (\"syscall\" : \"=a\"(ret) : \"a\"(n), \"D\"(a1), \"S\"(a2), \"d\"(a3), \"r\"(r10), \"r\"(r8), \"r\"(r9) : \"rcx\", \"r11\", \"memory\");"));
    hl_list_push(u_r, hl_cstr("#elif defined(__aarch64__) || defined(__riscv) || defined(__riscv__)"));
    hl_list_push(u_r, hl_cstr("    register long x8 __asm__(\"x8\") = n;"));
    hl_list_push(u_r, hl_cstr("    (void)x8;"));
    hl_list_push(u_r, hl_cstr("    __asm__ volatile (\"svc #0\" : \"=r\"(ret) : \"r\"(x8), \"r\"(a1), \"r\"(a2), \"r\"(a3), \"r\"(a4), \"r\"(a5), \"r\"(a6) : \"memory\");"));
    hl_list_push(u_r, hl_cstr("#else"));
    hl_list_push(u_r, hl_cstr("    (void)a1; (void)a2; (void)a3; (void)a4; (void)a5; (void)a6;"));
    hl_list_push(u_r, hl_cstr("    ret = -1L;"));
    hl_list_push(u_r, hl_cstr("#endif"));
    hl_list_push(u_r, hl_cstr("    return ret;"));
    hl_list_push(u_r, hl_cstr("}"));
    hl_list_push(u_r, hl_cstr("static long hl_nl_mmap_zero(size_t n) {"));
    hl_list_push(u_r, hl_cstr("    // anonymous private mmap: reserve the arena's address space;"));
    hl_list_push(u_r, hl_cstr("    // Linux commits pages as they are touched, so reserving 1 GiB"));
    hl_list_push(u_r, hl_cstr("    // of virtual address space costs RSS only for the pages the"));
    hl_list_push(u_r, hl_cstr("    // compiler actually touches."));
    hl_list_push(u_r, hl_cstr("    return hl_nl_sys(HL_SYS_mmap, 0L, (long)n, 3L, 0x22L, -1L, 0L);"));
    hl_list_push(u_r, hl_cstr("}"));
    hl_list_push(u_r, hl_cstr("// ---- Stage 92: the mmap-backed bump arena ----"));
    hl_list_push(u_r, hl_cstr("// Same shape as the freestanding arena (8-byte size header,"));
    hl_list_push(u_r, hl_cstr("// realloc copies), but the backing store is RESERVED virtual"));
    hl_list_push(u_r, hl_cstr("// memory committed lazily, because a self-hosting compile"));
    hl_list_push(u_r, hl_cstr("// allocates tens of MB of tokens, AST and generated text."));
    hl_list_push(u_r, hl_cstr("#define HL_HEAP_RESERVE ((size_t)1073741824)"));
    hl_list_push(u_r, hl_cstr("static unsigned char* hl_heap_base = 0;"));
    hl_list_push(u_r, hl_cstr("static size_t hl_heap_pos = 0;"));
    hl_list_push(u_r, hl_cstr("static void* hl_bump_alloc(size_t n) {"));
    hl_list_push(u_r, hl_cstr("    size_t total = n + (size_t)8;"));
    hl_list_push(u_r, hl_cstr("    size_t a = (total + (size_t)15) & ~(size_t)15;"));
    hl_list_push(u_r, hl_cstr("    if (a < total) __builtin_trap();"));
    hl_list_push(u_r, hl_cstr("    if (!hl_heap_base) {"));
    hl_list_push(u_r, hl_cstr("        long p = hl_nl_mmap_zero(HL_HEAP_RESERVE);"));
    hl_list_push(u_r, hl_cstr("        if (p < 0) __builtin_trap();"));
    hl_list_push(u_r, hl_cstr("        hl_heap_base = (unsigned char*)p;"));
    hl_list_push(u_r, hl_cstr("    }"));
    hl_list_push(u_r, hl_cstr("    if (hl_heap_pos + a > HL_HEAP_RESERVE || hl_heap_pos + a < hl_heap_pos) __builtin_trap();"));
    hl_list_push(u_r, hl_cstr("    unsigned char* base = hl_heap_base + hl_heap_pos;"));
    hl_list_push(u_r, hl_cstr("    *(size_t*)base = n;"));
    hl_list_push(u_r, hl_cstr("    hl_heap_pos += a;"));
    hl_list_push(u_r, hl_cstr("    return (void*)(base + 8);"));
    hl_list_push(u_r, hl_cstr("}"));
    hl_list_push(u_r, hl_cstr("static void* hl_bump_calloc(size_t n, size_t sz) {"));
    hl_list_push(u_r, hl_cstr("    if (sz != 0 && n > (size_t)-1 / sz) __builtin_trap();"));
    hl_list_push(u_r, hl_cstr("    size_t t = n * sz;"));
    hl_list_push(u_r, hl_cstr("    unsigned char* p = (unsigned char*)hl_bump_alloc(t);"));
    hl_list_push(u_r, hl_cstr("    for (size_t i = 0; i < t; i++) p[i] = 0;"));
    hl_list_push(u_r, hl_cstr("    return (void*)p;"));
    hl_list_push(u_r, hl_cstr("}"));
    hl_list_push(u_r, hl_cstr("static void* hl_bump_realloc(void* old, size_t n) {"));
    hl_list_push(u_r, hl_cstr("    if (!old) return hl_bump_alloc(n);"));
    hl_list_push(u_r, hl_cstr("    size_t oldn = *((size_t*)((unsigned char*)old - 8));"));
    hl_list_push(u_r, hl_cstr("    unsigned char* p = (unsigned char*)hl_bump_alloc(n);"));
    hl_list_push(u_r, hl_cstr("    size_t c = oldn < n ? oldn : n;"));
    hl_list_push(u_r, hl_cstr("    for (size_t i = 0; i < c; i++) p[i] = ((unsigned char*)old)[i];"));
    hl_list_push(u_r, hl_cstr("    return (void*)p;"));
    hl_list_push(u_r, hl_cstr("}"));
    hl_list_push(u_r, hl_cstr("#define malloc hl_bump_alloc"));
    hl_list_push(u_r, hl_cstr("#define calloc hl_bump_calloc"));
    hl_list_push(u_r, hl_cstr("#define realloc hl_bump_realloc"));
