    hl_list_push(u_r, hl_cstr("    if (*s == '.') {"));
    hl_list_push(u_r, hl_cstr("        s++;"));
    hl_list_push(u_r, hl_cstr("        while (*s >= '0' && *s <= '9') { if (digits < 30) { m = m * 10.0L + (long double)(*s - '0'); digits++; exp10--; } s++; }"));
    hl_list_push(u_r, hl_cstr("    }"));
    hl_list_push(u_r, hl_cstr("    if (digits == 0) { if (end) *end = (char*)s; return 0.0; }"));
    hl_list_push(u_r, hl_cstr("    int esign = 1;"));
    hl_list_push(u_r, hl_cstr("    int eexp = 0;"));
    hl_list_push(u_r, hl_cstr("    if (*s == 'e' || *s == 'E') {"));
    hl_list_push(u_r, hl_cstr("        const char* save = s;"));
    hl_list_push(u_r, hl_cstr("        s++;"));
    hl_list_push(u_r, hl_cstr("        if (*s == '+') { s++; } else if (*s == '-') { esign = -1; s++; }"));
    hl_list_push(u_r, hl_cstr("        if (*s >= '0' && *s <= '9') {"));
    hl_list_push(u_r, hl_cstr("            while (*s >= '0' && *s <= '9') { if (eexp < 10000) eexp = eexp * 10 + (*s - '0'); s++; }"));
    hl_list_push(u_r, hl_cstr("        } else {"));
    hl_list_push(u_r, hl_cstr("            s = save;"));
    hl_list_push(u_r, hl_cstr("        }"));
    hl_list_push(u_r, hl_cstr("    }"));
    hl_list_push(u_r, hl_cstr("    exp10 += esign * eexp;"));
    hl_list_push(u_r, hl_cstr("    if (exp10 > 400) exp10 = 400;"));
    hl_list_push(u_r, hl_cstr("    if (exp10 < -400) exp10 = -400;"));
