            hl_list_push(u_r, hl_cstr("// Protocol (g_rt_mu guards every det field; the baton serialises"));
            hl_list_push(u_r, hl_cstr("// EXECUTION, the mutex serialises STATE \342\200\224 in det mode only the"));
            hl_list_push(u_r, hl_cstr("// baton holder runs user code, so the mutex is uncontended):"));
            hl_list_push(u_r, hl_cstr("//   - a communicating op enters (parks until the baton is its"));
            hl_list_push(u_r, hl_cstr("//     node's), runs, requeues ITSELF at the ready-queue tail and"));
            hl_list_push(u_r, hl_cstr("//     parks until its turn comes round again;"));
            hl_list_push(u_r, hl_cstr("//   - a blocking op parks in a channel's or task's wait list (FIFO);"));
            hl_list_push(u_r, hl_cstr("//   - a waker moves satisfied waiters to the ready queue BEFORE it"));
            hl_list_push(u_r, hl_cstr("//     requeues itself \342\200\224 the wakee runs ahead of the waker;"));
            hl_list_push(u_r, hl_cstr("//   - a spawned task's node is enqueued by the SPAWNER, before the"));
            hl_list_push(u_r, hl_cstr("//     spawner requeues itself \342\200\224 the child's first turn comes first;"));
            hl_list_push(u_r, hl_cstr("//   - a finished task retires (never requeues) and releases its"));
            hl_list_push(u_r, hl_cstr("//     join waiters; a task leaving the rotation with an EMPTY ready"));
            hl_list_push(u_r, hl_cstr("//     queue runs the deadlock scan: a satisfied-but-unwoken waiter"));
            hl_list_push(u_r, hl_cstr("//     is a scheduler bug (reported loudly), a live waiter is the"));
            hl_list_push(u_r, hl_cstr("//     canonical Stage 16 deadlock, and no waiter at all is a"));
            hl_list_push(u_r, hl_cstr("//     program simply finishing."));
