            hl_list_push(u_r, hl_cstr("        if (rl > 0 || sl > 0) any = 1;"));
            hl_list_push(u_r, hl_cstr("    }"));
            hl_list_push(u_r, hl_cstr("    if (any)"));
            hl_list_push(u_r, hl_cstr("        hl_die(\"deadlock: all tasks are blocked on channel operations (no possible progress)\");"));
            hl_list_push(u_r, hl_cstr("    // No waiter anywhere: the last runnable thread left the rotation"));
            hl_list_push(u_r, hl_cstr("    // with nothing parked \342\200\224 the program is finishing, not stuck."));
            hl_list_push(u_r, hl_cstr("}"));
            hl_list_push(u_r, hl_cstr("static void hl_det_pass_locked(void) {  // g_rt_mu HELD by the leaving owner"));
            hl_list_push(u_r, hl_cstr("    hl_det_node* nxt = hl_det_ready_pop();"));
            hl_list_push(u_r, hl_cstr("    if (nxt) g_det_owner = nxt;"));
