        hl_list_push(u_r, hl_cstr("// chan_new_bounded(cap) \342\200\224 send blocks while `cap` messages are pending."));
        hl_list_push(u_r, hl_cstr("// The checker rejects literal capacities < 1; dynamic ones die here."));
        hl_list_push(u_r, hl_cstr("static hl_chan* hl_chan_new_bounded(int64_t cap, void (*elem_release)(void*)) {"));
        hl_list_push(u_r, hl_cstr("    if (cap < 1) hl_die(\"chan_new_bounded() capacity must be >= 1\");"));
