        hl_list_push(u_r, hl_cstr(""));
        hl_list_push(u_r, hl_cstr("// clone() of a channel SHARES it (atomic refcount + 1) \342\200\224 the whole"));
        hl_list_push(u_r, hl_cstr("// point of a channel. This is the ONLY clone in the language that"));
        hl_list_push(u_r, hl_cstr("// does not produce an independent copy."));
        hl_list_push(u_r, hl_cstr("static hl_chan* hl_chan_clone(hl_chan* c) {"));
        hl_list_push(u_r, hl_cstr("    if (c) __atomic_fetch_add(&c->refcnt, 1, __ATOMIC_ACQ_REL);"));
        hl_list_push(u_r, hl_cstr("    return c;"));
        hl_list_push(u_r, hl_cstr("}"));
        hl_list_push(u_r, hl_cstr(""));
        hl_list_push(u_r, hl_cstr("static void hl_chan_release(void* pv) {"));
        hl_list_push(u_r, hl_cstr("    hl_chan* c = (hl_chan*)pv;"));
        hl_list_push(u_r, hl_cstr("    if (!c) return;"));
        hl_list_push(u_r, hl_cstr("    if (__atomic_fetch_sub(&c->refcnt, 1, __ATOMIC_ACQ_REL) == 1) {"));
        hl_list_push(u_r, hl_cstr("        // Last reference. v0.29.0-alpha: first unlink the channel"));
        hl_list_push(u_r, hl_cstr("        // from the live-channel registry (the deadlock scan must"));
        hl_list_push(u_r, hl_cstr("        // not walk a freed node). No waiter can exist: refcnt==0"));
        hl_list_push(u_r, hl_cstr("        // means no binding holds the channel, and every"));
        hl_list_push(u_r, hl_cstr("        // send/recv requires a live reference \342\200\224 so send_waiters =="));
        hl_list_push(u_r, hl_cstr("        // waiters == 0 here. The drain then runs WITHOUT the lock;"));
        hl_list_push(u_r, hl_cstr("        // releasing payload channels re-enters safely (no nesting)."));
        hl_list_push(u_r, hl_cstr("        pthread_mutex_lock(&g_rt_mu);"));
        hl_list_push(u_r, hl_cstr("        hl_chan_unregister(c);"));
        hl_list_push(u_r, hl_cstr("        pthread_mutex_unlock(&g_rt_mu);"));
        hl_list_push(u_r, hl_cstr("        hl_msg* m = c->head;"));
        hl_list_push(u_r, hl_cstr("        while (m) {"));
        hl_list_push(u_r, hl_cstr("            hl_msg* nx = m->next;"));
        hl_list_push(u_r, hl_cstr("            if (c->elem_release && m->v.p) c->elem_release(m->v.p);"));
        hl_list_push(u_r, hl_cstr("            free(m);"));
        hl_list_push(u_r, hl_cstr("            m = nx;"));
        hl_list_push(u_r, hl_cstr("        }"));
        hl_list_push(u_r, hl_cstr("        free(c);"));
        hl_list_push(u_r, hl_cstr("    }"));
        hl_list_push(u_r, hl_cstr("}"));
        hl_list_push(u_r, hl_cstr("static void hl_cleanup_chan(hl_chan** p) { hl_chan_release(*p); }"));
        hl_list_push(u_r, hl_cstr(""));
        hl_list_push(u_r, hl_cstr("// Blocking enqueue \342\200\224 g_rt_mu HELD. On a bounded channel, waits"));
        hl_list_push(u_r, hl_cstr("// while the queue holds `cap` messages (backpressure); a dequeue"));
        hl_list_push(u_r, hl_cstr("// broadcasts, which is what wakes a sender blocked here. Unbounded"));
        hl_list_push(u_r, hl_cstr("// channels (cap == 0) never block the sender."));
        hl_list_push(u_r, hl_cstr("static void hl_chan_enqueue(hl_chan* c, hl_msg* m) {  // g_rt_mu HELD"));
        hl_list_push(u_r, hl_cstr("    while (c->cap > 0 && c->count >= c->cap) {"));
        hl_list_push(u_r, hl_cstr("        c->send_waiters++;"));
        hl_list_push(u_r, hl_cstr("        g_rt_blocked++;"));
        hl_list_push(u_r, hl_cstr("        hl_rt_park_send(c);"));
        hl_list_push(u_r, hl_cstr("        g_rt_blocked--;"));
        hl_list_push(u_r, hl_cstr("        c->send_waiters--;"));
        hl_list_push(u_r, hl_cstr("    }"));
        hl_list_push(u_r, hl_cstr("    if (c->tail) { c->tail->next = m; } else { c->head = m; }"));
