        hl_list_push(u_r, hl_cstr("    hl_rt_wake_recv(c);"));
        hl_list_push(u_r, hl_cstr("}"));
        hl_list_push(u_r, hl_cstr(""));
        hl_list_push(u_r, hl_cstr("static hl_msg* hl_chan_dequeue(hl_chan* c) {  // g_rt_mu HELD"));
        hl_list_push(u_r, hl_cstr("    hl_msg* m = c->head;"));
