        hl_list_push(u_r, hl_cstr("// select(chs) \342\200\224 block until any channel has a pending message;"));
        hl_list_push(u_r, hl_cstr("// return the index (list order) of the first ready one. The list"));
        hl_list_push(u_r, hl_cstr("// holds raw hl_chan* items (pointer element lists are unboxed)."));
        hl_list_push(u_r, hl_cstr("// v0.29.0-alpha: while waiting, the waiter count is bumped on ALL"));
        hl_list_push(u_r, hl_cstr("// listed channels so the deadlock scan sees this thread as a"));
        hl_list_push(u_r, hl_cstr("// potential consumer of any of them."));
        hl_list_push(u_r, hl_cstr("static int64_t hl_chan_select(hl_list* chs) {"));
        hl_list_push(u_r, hl_cstr("    hl_chan_select_det_op(chs);"));
        hl_list_push(u_r, hl_cstr("    pthread_mutex_lock(&g_rt_mu);"));
        hl_list_push(u_r, hl_cstr("    if (chs->len == 0) {"));
        hl_list_push(u_r, hl_cstr("        pthread_mutex_unlock(&g_rt_mu);"));
        hl_list_push(u_r, hl_cstr("        hl_die(\"select() on empty channel list\");"));
        hl_list_push(u_r, hl_cstr("    }"));
        hl_list_push(u_r, hl_cstr("    while (1) {"));
        hl_list_push(u_r, hl_cstr("        for (int64_t i = 0; i < chs->len; i++) {"));
        hl_list_push(u_r, hl_cstr("            hl_chan* c = (hl_chan*)chs->items[i];"));
        hl_list_push(u_r, hl_cstr("            if (c->head) {"));
        hl_list_push(u_r, hl_cstr("                int64_t r = i;"));
        hl_list_push(u_r, hl_cstr("                hl_rt_wake_send(c);"));
        hl_list_push(u_r, hl_cstr("                pthread_mutex_unlock(&g_rt_mu);"));
        hl_list_push(u_r, hl_cstr("                hl_det_yield();"));
        hl_list_push(u_r, hl_cstr("                return r;"));
        hl_list_push(u_r, hl_cstr("            }"));
        hl_list_push(u_r, hl_cstr("        }"));
        hl_list_push(u_r, hl_cstr("        for (int64_t i = 0; i < chs->len; i++)"));
        hl_list_push(u_r, hl_cstr("            ((hl_chan*)chs->items[i])->waiters++;"));
        hl_list_push(u_r, hl_cstr("        g_rt_blocked++;"));
        hl_list_push(u_r, hl_cstr("        hl_rt_park_select(chs);"));
        hl_list_push(u_r, hl_cstr("        g_rt_blocked--;"));
        hl_list_push(u_r, hl_cstr("        for (int64_t i = 0; i < chs->len; i++)"));
        hl_list_push(u_r, hl_cstr("            ((hl_chan*)chs->items[i])->waiters--;"));
        hl_list_push(u_r, hl_cstr("    }"));
        hl_list_push(u_r, hl_cstr("}"));
        hl_list_push(u_r, hl_cstr(""));
        hl_list_push(u_r, hl_cstr("// ---- tasks ----"));
        hl_list_push(u_r, hl_cstr("static void hl_task_finish(hl_task* t, hl_task_res res) {"));
        hl_list_push(u_r, hl_cstr("    hl_det_op(\"finish\", NULL);"));
        hl_list_push(u_r, hl_cstr("    pthread_mutex_lock(&g_rt_mu);"));
