        hl_list_push(u_r, hl_cstr(""));
        hl_list_push(u_r, hl_cstr("#define HL_TASK_STACK_BYTES  (1024 * 1024)   /* 1 MiB usable, deterministic */"));
        hl_list_push(u_r, hl_cstr("#define HL_TASK_GUARD_BYTES  4096              /* one PROT_NONE guard page */"));
        hl_list_push(u_r, hl_cstr(""));
        hl_list_push(u_r, hl_cstr("static int hl_thread_start(pthread_t* th, void* (*fn)(void*), void* arg) {"));
        hl_list_push(u_r, hl_cstr("    pthread_attr_t at;"));
        hl_list_push(u_r, hl_cstr("    if (pthread_attr_init(&at) != 0) {"));
        hl_list_push(u_r, hl_cstr("        /* No attr support: fall back to the default stack. */"));
        hl_list_push(u_r, hl_cstr("        return pthread_create(th, NULL, fn, arg);"));
        hl_list_push(u_r, hl_cstr("    }"));
        hl_list_push(u_r, hl_cstr("    pthread_attr_setstacksize(&at, HL_TASK_STACK_BYTES);"));
        hl_list_push(u_r, hl_cstr("    pthread_attr_setguardsize(&at, HL_TASK_GUARD_BYTES);"));
        hl_list_push(u_r, hl_cstr("    int rc = pthread_create(th, &at, fn, arg);"));
        hl_list_push(u_r, hl_cstr("    pthread_attr_destroy(&at);"));
        hl_list_push(u_r, hl_cstr("    return rc;"));
        hl_list_push(u_r, hl_cstr("}"));
        hl_list_push(u_r, hl_cstr(""));
        hl_list_push(u_r, hl_cstr("static hl_task* hl_spawn(void (*body)(void*, hl_task*), void* argbox) {"));
        hl_list_push(u_r, hl_cstr("    int64_t det_id = -1;"));
