        hl_list_push(u_r, hl_cstr("    if (!c) hl_die(\"out of memory\");"));
        hl_list_push(u_r, hl_cstr("    c->body = body;"));
        hl_list_push(u_r, hl_cstr("    c->argbox = argbox;"));
        hl_list_push(u_r, hl_cstr("    c->task = t;"));
        hl_list_push(u_r, hl_cstr("    c->det_node = dn;"));
        hl_list_push(u_r, hl_cstr("    pthread_mutex_lock(&g_rt_mu);"));
        hl_list_push(u_r, hl_cstr("    g_rt_tasks++;   // counted BEFORE the thread starts: no deadlock false-positive window"));
        hl_list_push(u_r, hl_cstr("    pthread_mutex_unlock(&g_rt_mu);"));
        hl_list_push(u_r, hl_cstr("    if (hl_thread_start(&t->th, hl_spawn_entry, c) != 0) {"));
        hl_list_push(u_r, hl_cstr("        pthread_mutex_lock(&g_rt_mu);"));
        hl_list_push(u_r, hl_cstr("        g_rt_tasks--;"));
        hl_list_push(u_r, hl_cstr("        pthread_mutex_unlock(&g_rt_mu);"));
        hl_list_push(u_r, hl_cstr("        hl_det_node_retire(dn);   // the queued child never runs"));
