    hl_list_push(u_r, hl_cstr("}"));
    hl_list_push(u_r, hl_cstr("static void hl_cleanup_map(hl_map** p) { hl_map_release(*p); }"));
    hl_list_push(u_r, hl_cstr(""));
    hl_list_push(u_r, hl_cstr("static void hl_map_grow(hl_map* m, int64_t ncap) {"));
    hl_list_push(u_r, hl_cstr("    hl_str** nslots = (hl_str**)calloc((size_t)ncap, sizeof(hl_str*));"));
    hl_list_push(u_r, hl_cstr("    void** nvals = (void**)malloc((size_t)ncap * sizeof(void*));"));
    hl_list_push(u_r, hl_cstr("    hl_str** norder = (hl_str**)malloc((size_t)ncap * sizeof(hl_str*));"));
    hl_list_push(u_r, hl_cstr("    if (!nslots || !nvals || !norder) hl_die(\"out of memory\");"));
    hl_list_push(u_r, hl_cstr("    for (int64_t i = 0; i < m->cap; i++) {"));
