    hl_list_push(u_r, hl_cstr("    }"));
    hl_list_push(u_r, hl_cstr("    for (int64_t j = 0; j < m->len; j++) norder[j] = m->order[j];"));
    hl_list_push(u_r, hl_cstr("    free(m->slots);"));
    hl_list_push(u_r, hl_cstr("    free(m->vals);"));
    hl_list_push(u_r, hl_cstr("    free(m->order);"));
    hl_list_push(u_r, hl_cstr("    m->slots = nslots;"));
    hl_list_push(u_r, hl_cstr("    m->vals = nvals;"));
    hl_list_push(u_r, hl_cstr("    m->order = norder;"));
    hl_list_push(u_r, hl_cstr("    m->cap = ncap;"));
    hl_list_push(u_r, hl_cstr("}"));
    hl_list_push(u_r, hl_cstr(""));
    hl_list_push(u_r, hl_cstr("// hl_map_set: k and v arrive OWNED (the caller transferred one retain"));
    hl_list_push(u_r, hl_cstr("// of each). On overwrite the incoming key is released and the old"));
    hl_list_push(u_r, hl_cstr("// value is released. Store-then-release keeps self-assignment safe."));
