    hl_list_push(u_r, hl_cstr("    if ((m->len + 1) * 10 >= m->cap * 7) {"));
    hl_list_push(u_r, hl_cstr("        hl_map_grow(m, m->cap * 2);"));
    hl_list_push(u_r, hl_cstr("    }"));
    hl_list_push(u_r, hl_cstr("    uint64_t idx = hl_str_hash(k) & (uint64_t)(m->cap - 1);"));
    hl_list_push(u_r, hl_cstr("    while (m->slots[idx] != NULL) {"));
    hl_list_push(u_r, hl_cstr("        if (hl_str_eq(m->slots[idx], k)) {"));
