    hl_list_push(u_r, hl_cstr("            hl_str_release(k);"));
    hl_list_push(u_r, hl_cstr("            return;"));
    hl_list_push(u_r, hl_cstr("        }"));
    hl_list_push(u_r, hl_cstr("        idx = (idx + 1) & (uint64_t)(m->cap - 1);"));
    hl_list_push(u_r, hl_cstr("    }"));
    hl_list_push(u_r, hl_cstr("    m->slots[idx] = k;"));
    hl_list_push(u_r, hl_cstr("    m->vals[idx] = v;"));
    hl_list_push(u_r, hl_cstr("    m->order[m->len] = k;"));
    hl_list_push(u_r, hl_cstr("    m->len++;"));
    hl_list_push(u_r, hl_cstr("}"));
    hl_list_push(u_r, hl_cstr(""));
    hl_list_push(u_r, hl_cstr("// hl_map_borrow: raw lookup \342\200\224 returns the stored slot value (a box for"));
