        hl_list_push(u_r, hl_cstr("// The mark: the program printed `__HLRT_CYCLE__ <i>` (the scan in"));
        hl_list_push(u_r, hl_cstr("// hl_println checked the reserved prefix; this function owns the"));
        hl_list_push(u_r, hl_cstr("// rest). Order matters and is the mode's contract:"));
        hl_list_push(u_r, hl_cstr("//   1. roll the instrument \342\200\224 the just-closed cycle becomes the"));
        hl_list_push(u_r, hl_cstr("//      snapshot and enters the ledger BEFORE anything can die, so"));
        hl_list_push(u_r, hl_cstr("//      the atexit report holds the violating cycle's numbers too;"));
        hl_list_push(u_r, hl_cstr("//   2. stamp the clock (every armed mark, warmup included \342\200\224 the"));
        hl_list_push(u_r, hl_cstr("//      next measured cycle's window starts here either way);"));
        hl_list_push(u_r, hl_cstr("//   3. enforce, warmup cycles excluded, in the canonical axis"));
        hl_list_push(u_r, hl_cstr("//      order (allocs, bytes, nanos) \342\200\224 the first violation dies"));
        hl_list_push(u_r, hl_cstr("//      with the exact message core/rt.hls renders."));
        hl_list_push(u_r, hl_cstr("static void hl_srt_on_mark(const char* digits, int64_t len) {"));
        hl_list_push(u_r, hl_cstr("    if (!hl_srt_armed) return;"));
