        hl_list_push(u_r, hl_cstr("    if (idx < 0) return;   // the verifier flags a malformed record; the"));
        hl_list_push(u_r, hl_cstr("                           // runtime just refuses to roll on one"));
        hl_list_push(u_r, hl_cstr("    hlrt_cycle_mark(idx);"));
