        hl_list_push(u_r, hl_cstr("                (long long)idx, (long long)a, (long long)hl_srt_max_allocs);"));
        hl_list_push(u_r, hl_cstr("            hl_die(msg);"));
        hl_list_push(u_r, hl_cstr("        }"));
        hl_list_push(u_r, hl_cstr("    }"));
        hl_list_push(u_r, hl_cstr("    if (hl_srt_max_bytes > 0) {"));
        hl_list_push(u_r, hl_cstr("        int64_t b = hlrt_cycle_bytes();"));
        hl_list_push(u_r, hl_cstr("        if (b > hl_srt_max_bytes) {"));
        hl_list_push(u_r, hl_cstr("            snprintf(msg, sizeof msg,"));
        hl_list_push(u_r, hl_cstr("                \"soft real-time violation: cycle %lld allocated %lld bytes (budget %lld)\","));
        hl_list_push(u_r, hl_cstr("                (long long)idx, (long long)b, (long long)hl_srt_max_bytes);"));
        hl_list_push(u_r, hl_cstr("            hl_die(msg);"));
        hl_list_push(u_r, hl_cstr("        }"));
        hl_list_push(u_r, hl_cstr("    }"));
        hl_list_push(u_r, hl_cstr("    if (hl_srt_max_nanos > 0 && cycle_ns > hl_srt_max_nanos) {"));
        hl_list_push(u_r, hl_cstr("        snprintf(msg, sizeof msg,"));
        hl_list_push(u_r, hl_cstr("            \"soft real-time violation: cycle %lld took %lld ns (deadline %lld ns)\","));
        hl_list_push(u_r, hl_cstr("            (long long)idx, (long long)cycle_ns, (long long)hl_srt_max_nanos);"));
        hl_list_push(u_r, hl_cstr("        hl_die(msg);"));
