    hl_list_push(u_r, hl_cstr("// hl_read_file: consumes the path, returns a fresh str. The temporary"));
    hl_list_push(u_r, hl_cstr("// read buffer is freed before returning (it used to leak under the"));
    hl_list_push(u_r, hl_cstr("// arena model)."));
    hl_list_push(u_r, hl_cstr("static hl_str* hl_read_file(hl_str* path) {"));
    hl_list_push(u_r, hl_cstr("    hl_sandbox_check(path->data);"));
    hl_list_push(u_r, hl_cstr("    FILE* f = fopen(path->data, \"rb\");"));
    hl_list_push(u_r, hl_cstr("    if (!f) hl_die(\"cannot open file\");"));
    hl_list_push(u_r, hl_cstr("    // Virtual files (/proc, /sys) report size 0 via fseek/ftell,"));
    hl_list_push(u_r, hl_cstr("    // so read incrementally until EOF instead of trusting the"));
    hl_list_push(u_r, hl_cstr("    // size (BUG: the interpreter read them fine while the native"));
    hl_list_push(u_r, hl_cstr("    // binary got empty output \342\200\224 a differential divergence)."));
    hl_list_push(u_r, hl_cstr("    size_t cap = 4096, len = 0;"));
    hl_list_push(u_r, hl_cstr("    char* buf = (char*)malloc(cap);"));
    hl_list_push(u_r, hl_cstr("    if (!buf) hl_die(\"out of memory\");"));
    hl_list_push(u_r, hl_cstr("    for (;;) {"));
    hl_list_push(u_r, hl_cstr("        if (len == cap) {"));
    hl_list_push(u_r, hl_cstr("            size_t new_cap = cap * 2;"));
    hl_list_push(u_r, hl_cstr("            // Deep-scan fix (C10): realloc-on-failure leaks the"));
    hl_list_push(u_r, hl_cstr("            // original buffer. Use a temp so the original is"));
    hl_list_push(u_r, hl_cstr("            // still freeable on OOM."));
    hl_list_push(u_r, hl_cstr("            char* nb = (char*)realloc(buf, new_cap);"));
    hl_list_push(u_r, hl_cstr("            if (!nb) { free(buf); hl_die(\"out of memory\"); }"));
    hl_list_push(u_r, hl_cstr("            buf = nb;"));
    hl_list_push(u_r, hl_cstr("            cap = new_cap;"));
    hl_list_push(u_r, hl_cstr("        }"));
    hl_list_push(u_r, hl_cstr("        size_t n = fread(buf + len, 1, cap - len, f);"));
    hl_list_push(u_r, hl_cstr("        len += n;"));
    hl_list_push(u_r, hl_cstr("        if (n == 0) break;"));
    hl_list_push(u_r, hl_cstr("    }"));
    hl_list_push(u_r, hl_cstr("    fclose(f);"));
    hl_list_push(u_r, hl_cstr("    hl_str* out = hl_str_from(buf, (int64_t)len);"));
    hl_list_push(u_r, hl_cstr("    free(buf);"));
    hl_list_push(u_r, hl_cstr("    hl_str_release(path);"));
    hl_list_push(u_r, hl_cstr("    return out;"));
    hl_list_push(u_r, hl_cstr("}"));
