    hl_list_push(u_r, hl_cstr("// Stage 10 release: hl_read_line() \342\200\224 read one line from stdin."));
    hl_list_push(u_r, hl_cstr("// Strips a trailing newline (and CRLF if present). Returns a fresh"));
    hl_list_push(u_r, hl_cstr("// hl_str* (refcount 1) owned by the caller. At EOF, returns an"));
    hl_list_push(u_r, hl_cstr("// empty string (mirrors fgets semantics). The Stage-0 interpreter"));
    hl_list_push(u_r, hl_cstr("// strips CRLF the same way so differential testing stays green."));
    hl_list_push(u_r, hl_cstr("static hl_str* hl_read_line(void) {"));
    hl_list_push(u_r, hl_cstr("    size_t cap = 128, len = 0;"));
    hl_list_push(u_r, hl_cstr("    char* buf = (char*)malloc(cap);"));
    hl_list_push(u_r, hl_cstr("    if (!buf) hl_die(\"out of memory\");"));
    hl_list_push(u_r, hl_cstr("    for (;;) {"));
    hl_list_push(u_r, hl_cstr("        int c = getchar();"));
    hl_list_push(u_r, hl_cstr("        if (c == EOF) break;"));
    hl_list_push(u_r, hl_cstr("        if (len + 1 >= cap) {"));
    hl_list_push(u_r, hl_cstr("            cap *= 2;"));
    hl_list_push(u_r, hl_cstr("            char* nb = (char*)realloc(buf, cap);"));
    hl_list_push(u_r, hl_cstr("            if (!nb) { free(buf); hl_die(\"out of memory\"); }"));
    hl_list_push(u_r, hl_cstr("            buf = nb;"));
    hl_list_push(u_r, hl_cstr("        }"));
    hl_list_push(u_r, hl_cstr("        buf[len++] = (char)c;"));
    hl_list_push(u_r, hl_cstr("        if (c == '\\n') break;"));
    hl_list_push(u_r, hl_cstr("    }"));
    hl_list_push(u_r, hl_cstr("    // Strip trailing \\n and \\r\\n."));
    hl_list_push(u_r, hl_cstr("    if (len > 0 && buf[len - 1] == '\\n') {"));
    hl_list_push(u_r, hl_cstr("        len--;"));
    hl_list_push(u_r, hl_cstr("        if (len > 0 && buf[len - 1] == '\\r') len--;"));
    hl_list_push(u_r, hl_cstr("    }"));
    hl_list_push(u_r, hl_cstr("    hl_str* out = hl_str_from(buf, (int64_t)len);"));
    hl_list_push(u_r, hl_cstr("    free(buf);"));
    hl_list_push(u_r, hl_cstr("    return out;"));
    hl_list_push(u_r, hl_cstr("}"));
