    hl_list_push(u_r, hl_cstr("static void hl_thread_sleep_ms(int64_t ms) {"));
    hl_list_push(u_r, hl_cstr("    if (ms < 0) hl_die(\"thread_sleep_ms: duration must be >= 0\");"));
    hl_list_push(u_r, hl_cstr("    if (ms == 0) {"));
    hl_list_push(u_r, hl_cstr("        // Sleep(0) on POSIX: yield via sched_yield, not nanosleep(0)."));
    hl_list_push(u_r, hl_cstr("        // nanosleep(0) is a no-op (returns immediately) which is"));
    hl_list_push(u_r, hl_cstr("        // correct but less scheduler-friendly than sched_yield."));
    hl_list_push(u_r, hl_cstr("        sched_yield();"));
    hl_list_push(u_r, hl_cstr("        return;"));
    hl_list_push(u_r, hl_cstr("    }"));
    hl_list_push(u_r, hl_cstr("    struct timespec req;"));
    hl_list_push(u_r, hl_cstr("    req.tv_sec = ms / 1000;"));
    hl_list_push(u_r, hl_cstr("    req.tv_nsec = (ms % 1000) * 1000000L;"));
    hl_list_push(u_r, hl_cstr("    while (nanosleep(&req, &req) == -1 && errno == EINTR) {"));
