    hl_list_push(u_r, hl_cstr("    while (i > 0 && s[i - 1] != '(') i--;"));
    hl_list_push(u_r, hl_cstr("    if (i == 0) return false;"));
    hl_list_push(u_r, hl_cstr("    i--; /* the loop stops with i one PAST the '(' */"));
