    hl_list_push(u_r, hl_cstr(""));
    hl_list_push(u_r, hl_cstr("static int64_t hl_proc_wait(int64_t hl_pid) {"));
    hl_list_push(u_r, hl_cstr("    if (hl_pid < 1 || hl_pid > HL_PROC_MAX_CHILDREN) return -1;"));
    hl_list_push(u_r, hl_cstr("    struct hl_proc_child* c = &hl_proc_children[hl_pid - 1];"));
    hl_list_push(u_r, hl_cstr("    if (c->os_pid == 0) return -1;"));
    hl_list_push(u_r, hl_cstr("    if (c->exited) return (int64_t)c->exit_status;"));
    hl_list_push(u_r, hl_cstr("    /* Close any open write ends so the child sees EOF on stdin. */"));
    hl_list_push(u_r, hl_cstr("    if (c->stdin_fd != -1) { close(c->stdin_fd); c->stdin_fd = -1; }"));
    hl_list_push(u_r, hl_cstr("    int status = 0;"));
    hl_list_push(u_r, hl_cstr("    if (waitpid(c->os_pid, &status, 0) < 0) {"));
    hl_list_push(u_r, hl_cstr("        return -1;"));
    hl_list_push(u_r, hl_cstr("    }"));
    hl_list_push(u_r, hl_cstr("    int encoded;"));
    hl_list_push(u_r, hl_cstr("#ifdef WIFEXITED"));
    hl_list_push(u_r, hl_cstr("    if (WIFEXITED(status)) encoded = WEXITSTATUS(status);"));
    hl_list_push(u_r, hl_cstr("    else if (WIFSIGNALED(status)) encoded = 128 + WTERMSIG(status);"));
    hl_list_push(u_r, hl_cstr("    else encoded = -1;"));
    hl_list_push(u_r, hl_cstr("#else"));
    hl_list_push(u_r, hl_cstr("    encoded = status & 0xFF;"));
    hl_list_push(u_r, hl_cstr("#endif"));
    hl_list_push(u_r, hl_cstr("    c->exited = 1;"));
    hl_list_push(u_r, hl_cstr("    c->exit_status = encoded;"));
    hl_list_push(u_r, hl_cstr("    return (int64_t)encoded;"));
    hl_list_push(u_r, hl_cstr("}"));
    hl_list_push(u_r, hl_cstr(""));
    hl_list_push(u_r, hl_cstr("static int64_t hl_proc_kill(int64_t hl_pid) {"));
    hl_list_push(u_r, hl_cstr("    if (hl_pid < 1 || hl_pid > HL_PROC_MAX_CHILDREN) return -1;"));
    hl_list_push(u_r, hl_cstr("    struct hl_proc_child* c = &hl_proc_children[hl_pid - 1];"));
    hl_list_push(u_r, hl_cstr("    if (c->os_pid == 0) return -1;"));
    hl_list_push(u_r, hl_cstr("    if (c->exited) return 0;"));
    hl_list_push(u_r, hl_cstr("    if (kill(c->os_pid, SIGTERM) < 0) {"));
    hl_list_push(u_r, hl_cstr("        /* ESRCH = child already reaped. Treat as success. */"));
    hl_list_push(u_r, hl_cstr("        if (errno == ESRCH) return 0;"));
    hl_list_push(u_r, hl_cstr("        return -1;"));
    hl_list_push(u_r, hl_cstr("    }"));
    hl_list_push(u_r, hl_cstr("    return 0;"));
    hl_list_push(u_r, hl_cstr("}"));
    hl_list_push(u_r, hl_cstr(""));
    hl_list_push(u_r, hl_cstr("static int64_t hl_proc_child_write(int64_t hl_pid, hl_str* data) {"));
    hl_list_push(u_r, hl_cstr("    if (hl_pid < 1 || hl_pid > HL_PROC_MAX_CHILDREN) {"));
    hl_list_push(u_r, hl_cstr("        hl_str_release(data);"));
    hl_list_push(u_r, hl_cstr("        return -1;"));
    hl_list_push(u_r, hl_cstr("    }"));
    hl_list_push(u_r, hl_cstr("    struct hl_proc_child* c = &hl_proc_children[hl_pid - 1];"));
    hl_list_push(u_r, hl_cstr("    if (c->os_pid == 0 || c->stdin_fd == -1) {"));
    hl_list_push(u_r, hl_cstr("        hl_str_release(data);"));
    hl_list_push(u_r, hl_cstr("        return -1;"));
    hl_list_push(u_r, hl_cstr("    }"));
    hl_list_push(u_r, hl_cstr("    ssize_t n = write(c->stdin_fd, data->data, (size_t)data->len);"));
    hl_list_push(u_r, hl_cstr("    hl_str_release(data);"));
    hl_list_push(u_r, hl_cstr("    if (n < 0) return -1;"));
    hl_list_push(u_r, hl_cstr("    return (int64_t)n;"));
    hl_list_push(u_r, hl_cstr("}"));
    hl_list_push(u_r, hl_cstr(""));
    hl_list_push(u_r, hl_cstr("static hl_str* hl_proc_child_read(int64_t hl_pid, int64_t fd_kind,"));
    hl_list_push(u_r, hl_cstr("                                int64_t n) {"));
    hl_list_push(u_r, hl_cstr("    if (hl_pid < 1 || hl_pid > HL_PROC_MAX_CHILDREN)"));
    hl_list_push(u_r, hl_cstr("        return hl_str_from(\"\", 0);"));
    hl_list_push(u_r, hl_cstr("    struct hl_proc_child* c = &hl_proc_children[hl_pid - 1];"));
    hl_list_push(u_r, hl_cstr("    if (c->os_pid == 0) return hl_str_from(\"\", 0);"));
    hl_list_push(u_r, hl_cstr("    int fd = -1;"));
    hl_list_push(u_r, hl_cstr("    if (fd_kind == 1) fd = c->stdout_fd;"));
    hl_list_push(u_r, hl_cstr("    else if (fd_kind == 2) fd = c->stderr_fd;"));
    hl_list_push(u_r, hl_cstr("    else return hl_str_from(\"\", 0);"));
    hl_list_push(u_r, hl_cstr("    if (fd == -1) return hl_str_from(\"\", 0);"));
    hl_list_push(u_r, hl_cstr("    if (n < 0) n = 0;"));
    hl_list_push(u_r, hl_cstr("    if (n > (64 * 1024 * 1024)) n = 64 * 1024 * 1024;  /* 64 MiB cap */"));
    hl_list_push(u_r, hl_cstr("    char* buf = (char*)malloc((size_t)n + 1);"));
    hl_list_push(u_r, hl_cstr("    if (!buf) return hl_str_from(\"\", 0);"));
    hl_list_push(u_r, hl_cstr("    ssize_t got = read(fd, buf, (size_t)n);"));
    hl_list_push(u_r, hl_cstr("    if (got < 0) got = 0;"));
    hl_list_push(u_r, hl_cstr("    hl_str* out = hl_str_from(buf, (int64_t)got);"));
    hl_list_push(u_r, hl_cstr("    free(buf);"));
    hl_list_push(u_r, hl_cstr("    return out;"));
    hl_list_push(u_r, hl_cstr("}"));
    hl_list_push(u_r, hl_cstr(""));
    hl_list_push(u_r, hl_cstr("static int64_t hl_proc_child_close(int64_t hl_pid, int64_t fd_kind) {"));
    hl_list_push(u_r, hl_cstr("    if (hl_pid < 1 || hl_pid > HL_PROC_MAX_CHILDREN) return -1;"));
    hl_list_push(u_r, hl_cstr("    struct hl_proc_child* c = &hl_proc_children[hl_pid - 1];"));
    hl_list_push(u_r, hl_cstr("    if (c->os_pid == 0) return -1;"));
    hl_list_push(u_r, hl_cstr("    if (fd_kind < 0 || fd_kind > 2) return -1;"));
    hl_list_push(u_r, hl_cstr("    int* fd_ptr;"));
    hl_list_push(u_r, hl_cstr("    if (fd_kind == 0) fd_ptr = &c->stdin_fd;"));
    hl_list_push(u_r, hl_cstr("    else if (fd_kind == 1) fd_ptr = &c->stdout_fd;"));
    hl_list_push(u_r, hl_cstr("    else fd_ptr = &c->stderr_fd;"));
    hl_list_push(u_r, hl_cstr("    if (*fd_ptr == -1) return 0;  /* idempotent */"));
    hl_list_push(u_r, hl_cstr("    if (close(*fd_ptr) < 0) {"));
    hl_list_push(u_r, hl_cstr("        *fd_ptr = -1;"));
    hl_list_push(u_r, hl_cstr("        return -1;"));
    hl_list_push(u_r, hl_cstr("    }"));
    hl_list_push(u_r, hl_cstr("    *fd_ptr = -1;"));
    hl_list_push(u_r, hl_cstr("    return 0;"));
    hl_list_push(u_r, hl_cstr("}"));
    hl_list_push(u_r, hl_cstr(""));
    hl_list_push(u_r, hl_cstr("// hl_env_get(key) \342\200\224 read an env var. Returns a fresh str (the"));
    hl_list_push(u_r, hl_cstr("// value, or \"\" if not found). Consumes the key."));
    hl_list_push(u_r, hl_cstr("static hl_str* hl_env_get(hl_str* key) {"));
    hl_list_push(u_r, hl_cstr("    const char* v = getenv(key->data);"));
    hl_list_push(u_r, hl_cstr("    hl_str* out;"));
    hl_list_push(u_r, hl_cstr("    if (v == NULL) {"));
    hl_list_push(u_r, hl_cstr("        out = hl_str_from(\"\", 0);"));
    hl_list_push(u_r, hl_cstr("    } else {"));
    hl_list_push(u_r, hl_cstr("        size_t n = strlen(v);"));
    hl_list_push(u_r, hl_cstr("        out = hl_str_from(v, (int64_t)n);"));
    hl_list_push(u_r, hl_cstr("    }"));
    hl_list_push(u_r, hl_cstr("    hl_str_release(key);"));
    hl_list_push(u_r, hl_cstr("    return out;"));
    hl_list_push(u_r, hl_cstr("}"));
    hl_list_push(u_r, hl_cstr(""));
    hl_list_push(u_r, hl_cstr("// hl_env_has(key) \342\200\224 check if an env var exists. Consumes key."));
    hl_list_push(u_r, hl_cstr("static bool hl_env_has(hl_str* key) {"));
    hl_list_push(u_r, hl_cstr("    bool found = (getenv(key->data) != NULL);"));
    hl_list_push(u_r, hl_cstr("    hl_str_release(key);"));
    hl_list_push(u_r, hl_cstr("    return found;"));
    hl_list_push(u_r, hl_cstr("}"));
    hl_list_push(u_r, hl_cstr(""));
    hl_list_push(u_r, hl_cstr("// hl_env_set(key, value) \342\200\224 set an env var. setenv copies the"));
    hl_list_push(u_r, hl_cstr("// strings; we release the hl_str* args after the call."));
    hl_list_push(u_r, hl_cstr("static void hl_env_set(hl_str* key, hl_str* value) {"));
    hl_list_push(u_r, hl_cstr("    setenv(key->data, value->data, 1);"));
