    hl_list_push(u_r, hl_cstr("}"));
    hl_list_push(u_r, hl_cstr(""));
    hl_list_push(u_r, hl_cstr("// hl_env_unset(key) \342\200\224 unset an env var. unsetenv is a no-op if"));
    hl_list_push(u_r, hl_cstr("// the var does not exist (no error)."));
