    hl_list_push(u_r, hl_cstr(""));
    hl_list_push(u_r, hl_cstr("// hl_cwd_get() \342\200\224 read the cwd. Returns a fresh str. The cwd is"));
    hl_list_push(u_r, hl_cstr("// always available on POSIX (no failure case). The buffer"));
    hl_list_push(u_r, hl_cstr("// grows as needed via getcwd(NULL, 0) \342\200\224 a glibc extension that"));
    hl_list_push(u_r, hl_cstr("// allocates the right size automatically. Falls back to a"));
    hl_list_push(u_r, hl_cstr("// fixed-size buffer on systems that don't support this."));
    hl_list_push(u_r, hl_cstr("static hl_str* hl_cwd_get(void) {"));
    hl_list_push(u_r, hl_cstr("    char* buf = getcwd(NULL, 0);"));
    hl_list_push(u_r, hl_cstr("    if (buf == NULL) {"));
    hl_list_push(u_r, hl_cstr("        return hl_str_from(\"\", 0);"));
    hl_list_push(u_r, hl_cstr("    }"));
    hl_list_push(u_r, hl_cstr("    size_t n = strlen(buf);"));
    hl_list_push(u_r, hl_cstr("    hl_str* out = hl_str_from(buf, (int64_t)n);"));
    hl_list_push(u_r, hl_cstr("    free(buf);"));
    hl_list_push(u_r, hl_cstr("    return out;"));
    hl_list_push(u_r, hl_cstr("}"));
    hl_list_push(u_r, hl_cstr(""));
    hl_list_push(u_r, hl_cstr("// hl_cwd_set(path) \342\200\224 change the cwd. Returns 0 on success,"));
    hl_list_push(u_r, hl_cstr("// -1 on error. Consumes the path."));
