    hl_list_push(u_r, hl_cstr("// hl_instant_now_ns() \342\200\224 monotonic nanoseconds (high-resolution)."));
    hl_list_push(u_r, hl_cstr("static int64_t hl_instant_now_ns(void) {"));
    hl_list_push(u_r, hl_cstr("#if defined(CLOCK_MONOTONIC)"));
    hl_list_push(u_r, hl_cstr("    struct timespec ts;"));
    hl_list_push(u_r, hl_cstr("    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {"));
    hl_list_push(u_r, hl_cstr("        return 0;"));
    hl_list_push(u_r, hl_cstr("    }"));
    hl_list_push(u_r, hl_cstr("    return (int64_t)ts.tv_sec * 1000000000LL + (int64_t)ts.tv_nsec;"));
    hl_list_push(u_r, hl_cstr("#else"));
    hl_list_push(u_r, hl_cstr("    /* Fallback: clock_ms * 1000000 \342\200\224 ms resolution. */"));
    hl_list_push(u_r, hl_cstr("    struct timeval tv;"));
    hl_list_push(u_r, hl_cstr("    if (gettimeofday(&tv, NULL) != 0) {"));
    hl_list_push(u_r, hl_cstr("        return 0;"));
    hl_list_push(u_r, hl_cstr("    }"));
    hl_list_push(u_r, hl_cstr("    return (int64_t)tv.tv_sec * 1000000000LL"));
    hl_list_push(u_r, hl_cstr("         + (int64_t)tv.tv_usec * 1000LL;"));
    hl_list_push(u_r, hl_cstr("#endif"));
    hl_list_push(u_r, hl_cstr("}"));
    hl_list_push(u_r, hl_cstr(""));
    hl_list_push(u_r, hl_cstr("// hl_system_time_now_ms() \342\200\224 wall-clock milliseconds since Unix epoch."));
    hl_list_push(u_r, hl_cstr("static int64_t hl_system_time_now_ms(void) {"));
    hl_list_push(u_r, hl_cstr("#if defined(CLOCK_REALTIME)"));
    hl_list_push(u_r, hl_cstr("    struct timespec ts;"));
    hl_list_push(u_r, hl_cstr("    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {"));
    hl_list_push(u_r, hl_cstr("        return 0;"));
    hl_list_push(u_r, hl_cstr("    }"));
    hl_list_push(u_r, hl_cstr("    return (int64_t)ts.tv_sec * 1000LL + (int64_t)ts.tv_nsec / 1000000LL;"));
    hl_list_push(u_r, hl_cstr("#else"));
    hl_list_push(u_r, hl_cstr("    struct timeval tv;"));
    hl_list_push(u_r, hl_cstr("    if (gettimeofday(&tv, NULL) != 0) {"));
    hl_list_push(u_r, hl_cstr("        return 0;"));
    hl_list_push(u_r, hl_cstr("    }"));
    hl_list_push(u_r, hl_cstr("    return (int64_t)tv.tv_sec * 1000LL + (int64_t)tv.tv_usec / 1000LL;"));
    hl_list_push(u_r, hl_cstr("#endif"));
    hl_list_push(u_r, hl_cstr("}"));
