    hl_list_push(u_r, hl_cstr("// hl_net_tcp_connect(host, port) \342\200\224 TCP connect to host:port."));
    hl_list_push(u_r, hl_cstr("// Returns the socket fd (>= 0) or -1 on failure. Consumes host."));
    hl_list_push(u_r, hl_cstr("static int64_t hl_net_tcp_connect(hl_str* host, int64_t port) {"));
    hl_list_push(u_r, hl_cstr("    struct addrinfo hints;"));
    hl_list_push(u_r, hl_cstr("    memset(&hints, 0, sizeof(hints));"));
    hl_list_push(u_r, hl_cstr("    hints.ai_family = AF_INET;"));
    hl_list_push(u_r, hl_cstr("    hints.ai_socktype = SOCK_STREAM;"));
    hl_list_push(u_r, hl_cstr("    struct addrinfo* res = NULL;"));
    hl_list_push(u_r, hl_cstr("    char port_buf[16];"));
    hl_list_push(u_r, hl_cstr("    snprintf(port_buf, sizeof(port_buf), \"%lld\", (long long)port);"));
    hl_list_push(u_r, hl_cstr("    int rc = getaddrinfo(host->data, port_buf, &hints, &res);"));
    hl_list_push(u_r, hl_cstr("    if (rc != 0 || res == NULL) {"));
    hl_list_push(u_r, hl_cstr("        hl_str_release(host);"));
    hl_list_push(u_r, hl_cstr("        return -1;"));
    hl_list_push(u_r, hl_cstr("    }"));
    hl_list_push(u_r, hl_cstr("    int fd = socket(res->ai_family, res->ai_socktype, res->ai_protocol);"));
    hl_list_push(u_r, hl_cstr("    if (fd < 0) {"));
    hl_list_push(u_r, hl_cstr("        freeaddrinfo(res);"));
    hl_list_push(u_r, hl_cstr("        hl_str_release(host);"));
    hl_list_push(u_r, hl_cstr("        return -1;"));
    hl_list_push(u_r, hl_cstr("    }"));
    hl_list_push(u_r, hl_cstr("    struct timeval tv;"));
    hl_list_push(u_r, hl_cstr("    tv.tv_sec = 5; tv.tv_usec = 0;"));
    hl_list_push(u_r, hl_cstr("    setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));"));
    hl_list_push(u_r, hl_cstr("    setsockopt(fd, SOL_SOCKET, SO_SNDTIMEO, &tv, sizeof(tv));"));
    hl_list_push(u_r, hl_cstr("    if (connect(fd, res->ai_addr, res->ai_addrlen) < 0) {"));
    hl_list_push(u_r, hl_cstr("        close(fd);"));
    hl_list_push(u_r, hl_cstr("        freeaddrinfo(res);"));
    hl_list_push(u_r, hl_cstr("        hl_str_release(host);"));
    hl_list_push(u_r, hl_cstr("        return -1;"));
    hl_list_push(u_r, hl_cstr("    }"));
    hl_list_push(u_r, hl_cstr("    freeaddrinfo(res);"));
    hl_list_push(u_r, hl_cstr("    hl_str_release(host);"));
    hl_list_push(u_r, hl_cstr("    return (int64_t)fd;"));
    hl_list_push(u_r, hl_cstr("}"));
    hl_list_push(u_r, hl_cstr(""));
    hl_list_push(u_r, hl_cstr("// hl_net_tcp_listen(host, port, backlog) \342\200\224 bind + listen. Returns"));
    hl_list_push(u_r, hl_cstr("// the listen fd or -1. SO_REUSEADDR is set so a restart doesn't"));
    hl_list_push(u_r, hl_cstr("// wait for TIME_WAIT. A 30s SO_RCVTIMEO bounds the accept()"));
    hl_list_push(u_r, hl_cstr("// wait on this socket: a listener whose client never comes"));
    hl_list_push(u_r, hl_cstr("// returns -1 after 30s instead of hanging the program (and"));
    hl_list_push(u_r, hl_cstr("// any task joining on it) forever \342\200\224 the same bound the"));
    hl_list_push(u_r, hl_cstr("// interpreter's settimeout(30) gives. Consumes host."));
    hl_list_push(u_r, hl_cstr("static int64_t hl_net_tcp_listen(hl_str* host, int64_t port, int64_t backlog) {"));
    hl_list_push(u_r, hl_cstr("    int fd = socket(AF_INET, SOCK_STREAM, 0);"));
    hl_list_push(u_r, hl_cstr("    if (fd < 0) {"));
    hl_list_push(u_r, hl_cstr("        hl_str_release(host);"));
    hl_list_push(u_r, hl_cstr("        return -1;"));
    hl_list_push(u_r, hl_cstr("    }"));
    hl_list_push(u_r, hl_cstr("    int yes = 1;"));
    hl_list_push(u_r, hl_cstr("    setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &yes, sizeof(yes));"));
    hl_list_push(u_r, hl_cstr("    struct timeval ltv;"));
    hl_list_push(u_r, hl_cstr("    ltv.tv_sec = 30; ltv.tv_usec = 0;"));
    hl_list_push(u_r, hl_cstr("    setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &ltv, sizeof(ltv));"));
    hl_list_push(u_r, hl_cstr("    struct sockaddr_in addr;"));
    hl_list_push(u_r, hl_cstr("    memset(&addr, 0, sizeof(addr));"));
    hl_list_push(u_r, hl_cstr("    addr.sin_family = AF_INET;"));
    hl_list_push(u_r, hl_cstr("    addr.sin_port = htons((uint16_t)port);"));
    hl_list_push(u_r, hl_cstr("    if (host->len == 0 || strcmp(host->data, \"0.0.0.0\") == 0) {"));
    hl_list_push(u_r, hl_cstr("        addr.sin_addr.s_addr = htonl(INADDR_ANY);"));
    hl_list_push(u_r, hl_cstr("    } else if (strcmp(host->data, \"127.0.0.1\") == 0 || strcmp(host->data, \"localhost\") == 0) {"));
    hl_list_push(u_r, hl_cstr("        addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);"));
    hl_list_push(u_r, hl_cstr("    } else if (inet_pton(AF_INET, host->data, &addr.sin_addr) != 1) {"));
    hl_list_push(u_r, hl_cstr("        close(fd);"));
    hl_list_push(u_r, hl_cstr("        hl_str_release(host);"));
    hl_list_push(u_r, hl_cstr("        return -1;"));
    hl_list_push(u_r, hl_cstr("    }"));
    hl_list_push(u_r, hl_cstr("    if (bind(fd, (struct sockaddr*)&addr, sizeof(addr)) < 0) {"));
    hl_list_push(u_r, hl_cstr("        close(fd);"));
    hl_list_push(u_r, hl_cstr("        hl_str_release(host);"));
    hl_list_push(u_r, hl_cstr("        return -1;"));
    hl_list_push(u_r, hl_cstr("    }"));
    hl_list_push(u_r, hl_cstr("    if (listen(fd, (int)backlog) < 0) {"));
    hl_list_push(u_r, hl_cstr("        close(fd);"));
    hl_list_push(u_r, hl_cstr("        hl_str_release(host);"));
    hl_list_push(u_r, hl_cstr("        return -1;"));
    hl_list_push(u_r, hl_cstr("    }"));
    hl_list_push(u_r, hl_cstr("    hl_str_release(host);"));
    hl_list_push(u_r, hl_cstr("    return (int64_t)fd;"));
    hl_list_push(u_r, hl_cstr("}"));
    hl_list_push(u_r, hl_cstr(""));
    hl_list_push(u_r, hl_cstr("// hl_net_tcp_accept(fd) \342\200\224 accept a connection. Returns the client"));
    hl_list_push(u_r, hl_cstr("// fd or -1 on error. The listen fd's 30s SO_RCVTIMEO bounds the"));
    hl_list_push(u_r, hl_cstr("// wait: with no peer, accept() returns EAGAIN after 30s (the"));
    hl_list_push(u_r, hl_cstr("// kernel honours the listening socket's receive timeout). The"));
    hl_list_push(u_r, hl_cstr("// accepted socket carries its own 30s send/recv timeouts."));
    hl_list_push(u_r, hl_cstr("static int64_t hl_net_tcp_accept(int64_t fd) {"));
    hl_list_push(u_r, hl_cstr("    int cfd = accept((int)fd, NULL, NULL);"));
    hl_list_push(u_r, hl_cstr("    if (cfd < 0) return -1;"));
    hl_list_push(u_r, hl_cstr("    struct timeval tv;"));
    hl_list_push(u_r, hl_cstr("    tv.tv_sec = 30; tv.tv_usec = 0;"));
    hl_list_push(u_r, hl_cstr("    setsockopt(cfd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));"));
    hl_list_push(u_r, hl_cstr("    setsockopt(cfd, SOL_SOCKET, SO_SNDTIMEO, &tv, sizeof(tv));"));
    hl_list_push(u_r, hl_cstr("    return (int64_t)cfd;"));
    hl_list_push(u_r, hl_cstr("}"));
    hl_list_push(u_r, hl_cstr(""));
    hl_list_push(u_r, hl_cstr("// hl_net_read(fd, n) \342\200\224 read up to n bytes from the socket."));
    hl_list_push(u_r, hl_cstr("// Returns a fresh str (refcnt=1). Empty str at EOF or on error."));
    hl_list_push(u_r, hl_cstr("// n is clamped to a 64 KiB cap to avoid unbounded allocation."));
    hl_list_push(u_r, hl_cstr("static hl_str* hl_net_read(int64_t fd, int64_t n) {"));
    hl_list_push(u_r, hl_cstr("    if (n <= 0) return hl_str_from(\"\", 0);"));
    hl_list_push(u_r, hl_cstr("    if (n > 65536) n = 65536;"));
    hl_list_push(u_r, hl_cstr("    char buf[65536];"));
    hl_list_push(u_r, hl_cstr("    ssize_t got = recv((int)fd, buf, (size_t)n, 0);"));
    hl_list_push(u_r, hl_cstr("    if (got <= 0) return hl_str_from(\"\", 0);"));
    hl_list_push(u_r, hl_cstr("    return hl_str_from(buf, (int64_t)got);"));
    hl_list_push(u_r, hl_cstr("}"));
    hl_list_push(u_r, hl_cstr(""));
    hl_list_push(u_r, hl_cstr("// hl_net_write(fd, data) \342\200\224 write all bytes. Returns bytes written"));
    hl_list_push(u_r, hl_cstr("// or -1 on error. Consumes data. Uses send() in a loop because"));
    hl_list_push(u_r, hl_cstr("// a single send() may not write all bytes for large payloads."));
    hl_list_push(u_r, hl_cstr("static int64_t hl_net_write(int64_t fd, hl_str* data) {"));
    hl_list_push(u_r, hl_cstr("    int64_t total = 0;"));
    hl_list_push(u_r, hl_cstr("    while (total < data->len) {"));
    hl_list_push(u_r, hl_cstr("        ssize_t w = send((int)fd, data->data + total,"));
    hl_list_push(u_r, hl_cstr("                         (size_t)(data->len - total), 0);"));
    hl_list_push(u_r, hl_cstr("        if (w <= 0) {"));
    hl_list_push(u_r, hl_cstr("            hl_str_release(data);"));
    hl_list_push(u_r, hl_cstr("            return -1;"));
    hl_list_push(u_r, hl_cstr("        }"));
    hl_list_push(u_r, hl_cstr("        total += w;"));
    hl_list_push(u_r, hl_cstr("    }"));
    hl_list_push(u_r, hl_cstr("    int64_t r = data->len;"));
    hl_list_push(u_r, hl_cstr("    hl_str_release(data);"));
    hl_list_push(u_r, hl_cstr("    return r;"));
    hl_list_push(u_r, hl_cstr("}"));
    hl_list_push(u_r, hl_cstr(""));
    hl_list_push(u_r, hl_cstr("// hl_net_close(fd) \342\200\224 close the socket. Idempotent (a double-close"));
    hl_list_push(u_r, hl_cstr("// is a silent no-op, matching the interpreter)."));
    hl_list_push(u_r, hl_cstr("static void hl_net_close(int64_t fd) {"));
    hl_list_push(u_r, hl_cstr("    if (fd >= 0) close((int)fd);"));
    hl_list_push(u_r, hl_cstr("}"));
    hl_list_push(u_r, hl_cstr(""));
    hl_list_push(u_r, hl_cstr("// hl_net_udp_open() \342\200\224 create a UDP socket. Returns fd or -1."));
    hl_list_push(u_r, hl_cstr("// A 5-second recv timeout is set so recv_from doesn't hang"));
    hl_list_push(u_r, hl_cstr("// forever on a dead peer (matches the interpreter)."));
    hl_list_push(u_r, hl_cstr("static int64_t hl_net_udp_open() {"));
    hl_list_push(u_r, hl_cstr("    int fd = socket(AF_INET, SOCK_DGRAM, 0);"));
    hl_list_push(u_r, hl_cstr("    if (fd < 0) return -1;"));
    hl_list_push(u_r, hl_cstr("    struct timeval tv;"));
    hl_list_push(u_r, hl_cstr("    tv.tv_sec = 5; tv.tv_usec = 0;"));
    hl_list_push(u_r, hl_cstr("    setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));"));
    hl_list_push(u_r, hl_cstr("    return (int64_t)fd;"));
    hl_list_push(u_r, hl_cstr("}"));
    hl_list_push(u_r, hl_cstr(""));
    hl_list_push(u_r, hl_cstr("// hl_net_udp_send_to(fd, host, port, data) \342\200\224 send a UDP datagram."));
    hl_list_push(u_r, hl_cstr("// Returns bytes sent or -1. Consumes host and data."));
    hl_list_push(u_r, hl_cstr("static int64_t hl_net_udp_send_to(int64_t fd, hl_str* host,"));
    hl_list_push(u_r, hl_cstr("                                 int64_t port, hl_str* data) {"));
    hl_list_push(u_r, hl_cstr("    struct addrinfo hints;"));
    hl_list_push(u_r, hl_cstr("    memset(&hints, 0, sizeof(hints));"));
    hl_list_push(u_r, hl_cstr("    hints.ai_family = AF_INET;"));
    hl_list_push(u_r, hl_cstr("    hints.ai_socktype = SOCK_DGRAM;"));
    hl_list_push(u_r, hl_cstr("    struct addrinfo* res = NULL;"));
    hl_list_push(u_r, hl_cstr("    char port_buf[16];"));
    hl_list_push(u_r, hl_cstr("    snprintf(port_buf, sizeof(port_buf), \"%lld\", (long long)port);"));
    hl_list_push(u_r, hl_cstr("    int rc = getaddrinfo(host->data, port_buf, &hints, &res);"));
    hl_list_push(u_r, hl_cstr("    hl_str_release(host);"));
    hl_list_push(u_r, hl_cstr("    if (rc != 0 || res == NULL) {"));
    hl_list_push(u_r, hl_cstr("        hl_str_release(data);"));
    hl_list_push(u_r, hl_cstr("        return -1;"));
    hl_list_push(u_r, hl_cstr("    }"));
    hl_list_push(u_r, hl_cstr("    ssize_t n = sendto((int)fd, data->data, (size_t)data->len, 0,"));
    hl_list_push(u_r, hl_cstr("                       res->ai_addr, res->ai_addrlen);"));
    hl_list_push(u_r, hl_cstr("    freeaddrinfo(res);"));
    hl_list_push(u_r, hl_cstr("    int64_t r = (n >= 0) ? (int64_t)n : -1;"));
    hl_list_push(u_r, hl_cstr("    hl_str_release(data);"));
    hl_list_push(u_r, hl_cstr("    return r;"));
    hl_list_push(u_r, hl_cstr("}"));
    hl_list_push(u_r, hl_cstr(""));
    hl_list_push(u_r, hl_cstr("// hl_net_udp_recv_from(fd, n) \342\200\224 receive a UDP datagram. Returns a"));
    hl_list_push(u_r, hl_cstr("// fresh str (refcnt=1). Empty str on error or timeout. The sender's"));
    hl_list_push(u_r, hl_cstr("// address is discarded (callers who need it should use the raw C"));
    hl_list_push(u_r, hl_cstr("// recvfrom directly via FFI \342\200\224 Stage 15)."));
    hl_list_push(u_r, hl_cstr("static hl_str* hl_net_udp_recv_from(int64_t fd, int64_t n) {"));
    hl_list_push(u_r, hl_cstr("    if (n <= 0) return hl_str_from(\"\", 0);"));
    hl_list_push(u_r, hl_cstr("    if (n > 65536) n = 65536;"));
    hl_list_push(u_r, hl_cstr("    char buf[65536];"));
    hl_list_push(u_r, hl_cstr("    ssize_t got = recvfrom((int)fd, buf, (size_t)n, 0, NULL, NULL);"));
    hl_list_push(u_r, hl_cstr("    if (got <= 0) return hl_str_from(\"\", 0);"));
    hl_list_push(u_r, hl_cstr("    return hl_str_from(buf, (int64_t)got);"));
    hl_list_push(u_r, hl_cstr("}"));
    hl_list_push(u_r, hl_cstr(""));
    hl_list_push(u_r, hl_cstr("typedef struct { char* data; int64_t len; int64_t cap; } hl_curl_buf;"));
    hl_list_push(u_r, hl_cstr("static size_t hl_curl_write_cb(char* ptr, size_t sz, size_t n, void* ud) {"));
    hl_list_push(u_r, hl_cstr("    hl_curl_buf* b = (hl_curl_buf*)ud;"));
    hl_list_push(u_r, hl_cstr("    size_t total = sz * n;"));
    hl_list_push(u_r, hl_cstr("    if (b->len + (int64_t)total > b->cap) {"));
    hl_list_push(u_r, hl_cstr("        int64_t newcap = b->cap * 2;"));
    hl_list_push(u_r, hl_cstr("        if (newcap < b->len + (int64_t)total) newcap = b->len + (int64_t)total;"));
    hl_list_push(u_r, hl_cstr("        char* nd = (char*)realloc(b->data, (size_t)newcap);"));
    hl_list_push(u_r, hl_cstr("        if (!nd) return 0;"));
    hl_list_push(u_r, hl_cstr("        b->data = nd; b->cap = newcap;"));
    hl_list_push(u_r, hl_cstr("    }"));
    hl_list_push(u_r, hl_cstr("    memcpy(b->data + b->len, ptr, total);"));
    hl_list_push(u_r, hl_cstr("    b->len += (int64_t)total;"));
    hl_list_push(u_r, hl_cstr("    return total;"));
    hl_list_push(u_r, hl_cstr("}"));
    hl_list_push(u_r, hl_cstr("static hl_str* hl_net_tls_get(hl_str* host, int64_t port, hl_str* path) {"));
    hl_list_push(u_r, hl_cstr("    if (path->len == 0 || path->data[0] != '/') {"));
    hl_list_push(u_r, hl_cstr("        char* nb = (char*)malloc((size_t)(path->len + 2));"));
    hl_list_push(u_r, hl_cstr("        if (!nb) { hl_str_release(host); hl_str_release(path); hl_die(\"net_tls_get: oom\"); }"));
    hl_list_push(u_r, hl_cstr("        nb[0] = '/';"));
    hl_list_push(u_r, hl_cstr("        memcpy(nb + 1, path->data, (size_t)path->len);"));
    hl_list_push(u_r, hl_cstr("        nb[path->len + 1] = 0;"));
    hl_list_push(u_r, hl_cstr("        hl_str* np = hl_str_from(nb, path->len + 1);"));
    hl_list_push(u_r, hl_cstr("        free(nb);"));
    hl_list_push(u_r, hl_cstr("        hl_str_release(path);"));
    hl_list_push(u_r, hl_cstr("        path = np;"));
    hl_list_push(u_r, hl_cstr("    }"));
    hl_list_push(u_r, hl_cstr("    char url[4096];"));
    hl_list_push(u_r, hl_cstr("    snprintf(url, sizeof(url), \"https://%s:%lld%s\","));
    hl_list_push(u_r, hl_cstr("             host->data, (long long)port, path->data);"));
    hl_list_push(u_r, hl_cstr("    (void)url;"));
    hl_list_push(u_r, hl_cstr("#ifdef HL_HAVE_LIBCURL"));
    hl_list_push(u_r, hl_cstr("    CURL* c = curl_easy_init();"));
    hl_list_push(u_r, hl_cstr("    if (!c) {"));
    hl_list_push(u_r, hl_cstr("        hl_str_release(host); hl_str_release(path);"));
    hl_list_push(u_r, hl_cstr("        hl_die(\"net_tls_get: curl_easy_init failed\");"));
    hl_list_push(u_r, hl_cstr("    }"));
    hl_list_push(u_r, hl_cstr("    hl_curl_buf buf;"));
    hl_list_push(u_r, hl_cstr("    buf.data = (char*)malloc(4096);"));
    hl_list_push(u_r, hl_cstr("    buf.len = 0; buf.cap = 4096;"));
    hl_list_push(u_r, hl_cstr("    if (!buf.data) {"));
    hl_list_push(u_r, hl_cstr("        curl_easy_cleanup(c);"));
    hl_list_push(u_r, hl_cstr("        hl_str_release(host); hl_str_release(path);"));
    hl_list_push(u_r, hl_cstr("        hl_die(\"net_tls_get: oom\");"));
    hl_list_push(u_r, hl_cstr("    }"));
    hl_list_push(u_r, hl_cstr("    curl_easy_setopt(c, CURLOPT_URL, url);"));
    hl_list_push(u_r, hl_cstr("    curl_easy_setopt(c, CURLOPT_WRITEFUNCTION, hl_curl_write_cb);"));
    hl_list_push(u_r, hl_cstr("    curl_easy_setopt(c, CURLOPT_WRITEDATA, &buf);"));
    hl_list_push(u_r, hl_cstr("    curl_easy_setopt(c, CURLOPT_FOLLOWLOCATION, 1L);"));
    hl_list_push(u_r, hl_cstr("    curl_easy_setopt(c, CURLOPT_TIMEOUT, 30L);"));
    hl_list_push(u_r, hl_cstr("    curl_easy_setopt(c, CURLOPT_FAILONERROR, 1L);"));
    hl_list_push(u_r, hl_cstr("    CURLcode rc = curl_easy_perform(c);"));
    hl_list_push(u_r, hl_cstr("    long http_code = 0;"));
    hl_list_push(u_r, hl_cstr("    curl_easy_getinfo(c, CURLINFO_RESPONSE_CODE, &http_code);"));
    hl_list_push(u_r, hl_cstr("    curl_easy_cleanup(c);"));
    hl_list_push(u_r, hl_cstr("    hl_str_release(host); hl_str_release(path);"));
    hl_list_push(u_r, hl_cstr("    if (rc != CURLE_OK) {"));
    hl_list_push(u_r, hl_cstr("        free(buf.data);"));
    hl_list_push(u_r, hl_cstr("        hl_die(\"net_tls_get: transport/TLS error\");"));
    hl_list_push(u_r, hl_cstr("    }"));
    hl_list_push(u_r, hl_cstr("    if (http_code >= 400) {"));
    hl_list_push(u_r, hl_cstr("        free(buf.data);"));
    hl_list_push(u_r, hl_cstr("        hl_die(\"net_tls_get: HTTP error\");"));
    hl_list_push(u_r, hl_cstr("    }"));
    hl_list_push(u_r, hl_cstr("    hl_str* out = hl_str_from(buf.data, buf.len);"));
    hl_list_push(u_r, hl_cstr("    free(buf.data);"));
    hl_list_push(u_r, hl_cstr("    return out;"));
    hl_list_push(u_r, hl_cstr("#else"));
    hl_list_push(u_r, hl_cstr("    hl_str_release(host); hl_str_release(path);"));
    hl_list_push(u_r, hl_cstr("    hl_die(\"net_tls_get: built without libcurl (rebuild with -DHAVE_LIBCURL and link -lcurl)\");"));
    hl_list_push(u_r, hl_cstr("#endif"));
    hl_list_push(u_r, hl_cstr("}"));
    hl_list_push(u_r, hl_cstr(""));
    hl_list_push(u_r, hl_cstr("// ---- v0.2 additions: pop, float, chr, fmod ----"));
    hl_list_push(u_r, hl_cstr("// String split helper (placed last because it depends on hl_list)"));
    hl_list_push(u_r, hl_cstr("static hl_list* hl_str_split(hl_str* s, hl_str* sep) {"));
